/* ============================================================
   SYSTEMS v2 — staff & economy, events & story, pharmacy, lab,
   dental, ward, differential board, office, library & quiz,
   collections, settings, backups, sharing, photo mode, co-op
   ============================================================ */

/* ---------------- staff & economy ---------------- */
function staffWages() { return G.s.staff.reduce((a, s) => a + s.wage, 0); }
function runningCosts() { return 40 + G.s.expansions.length * 25 + G.s.equipment.length * 5; }
function rebuildStaffNPCs() { Object.values(G.staffNPCs).forEach(n => World.removeNPC(n)); G.staffNPCs = {}; G.s.staff.forEach(s => { const n = World.addStaffNPC(s.role); if (n) G.staffNPCs[s.role] = n; }); }
function uiStaff() {
  const s = G.s; const roles = Object.keys(STAFF_ROLES);
  const rows = roles.map(r => { const R = STAFF_ROLES[r]; const have = s.staff.find(x => x.role === r); return `<div class="staffrow"><span class="icw">${icon({ receptionist: "bell", nurse: "steth", assistant: "scalpel", shopkeeper: "shop", cleaner: "drop" }[r], 24)}</span><div><b>${R.label}</b>${have ? ` — <b>${have.name}</b> (${have.level}, ${have.wage} JD/day, ${have.days} day(s) with you)` : ""}<br><span class="muted">${R.desc}</span><div class="btnrow tight">${have ? `${have.level === "junior" ? `<button class="btn small" onclick="trainStaff('${r}')">Train to senior (120 JD)</button>` : ""}<button class="btn small warn" onclick="fireStaff('${r}')">${T("Fire")}</button>` : `<button class="btn small primary" onclick="hireStaff('${r}','junior')">${T("Hire")} junior — ${R.wage.junior} JD/day</button><button class="btn small" onclick="hireStaff('${r}','senior')">${T("Hire")} senior — ${R.wage.senior} JD/day</button>`}</div></div></div>`; }).join("");
  openPanel(`${icon("user", 20)} Staff notice board`, `<p class="muted">Wages are paid at the end of every shift (currently <b>${staffWages()} JD/day</b> plus ${runningCosts()} JD rent & utilities). Miss payroll twice and staff walk out.</p>${rows}<h4>Hygiene score: ${s.hygiene}%</h4><p class="muted">Drops 6 points per day without a cleaner; below 60 % post-op infections and inspection failures become likely.</p>`, { wide: true });
}
function hireStaff(role, level) { const R = STAFF_ROLES[role]; if (G.s.staff.find(x => x.role === role)) return; if (G.s.money < R.wage[level]) return toast("You can't cover the first day's wage.", "warn"); G.s.staff.push({ role, level, wage: R.wage[level], name: pick(STAFF_NAMES), days: 0 }); Sound.success(); toast(`${R.label} hired. They start now.`, "good"); rebuildStaffNPCs(); award("boss"); uiStaff(); save(); }
function fireStaff(role) { const i = G.s.staff.findIndex(x => x.role === role); if (i < 0) return; const s = G.s.staff.splice(i, 1)[0]; toast(`${s.name} has left. Severance: ${s.wage} JD.`, "info"); G.s.money -= s.wage; rebuildStaffNPCs(); uiStaff(); updateHUD(); save(); }
function trainStaff(role) { const s = G.s.staff.find(x => x.role === role); if (!s || G.s.money < 120) return toast("Not enough money.", "warn"); G.s.money -= 120; s.level = "senior"; s.wage = STAFF_ROLES[role].wage.senior; Sound.success(); toast(`${s.name} completed training and is now senior.`, "good"); uiStaff(); updateHUD(); save(); }
function staffTick(dt) {
  const s = G.s; const st = (r) => s.staff.find(x => x.role === r);
  // receptionist auto-registers
  const rc = st("receptionist"); if (rc) { const p = patientAt("at_desk"); if (p && !p.emergency) { p.autoT = (p.autoT || 0) + dt; if (p.autoT > (rc.level === "senior" ? 8 : 14)) { p.greeted = true; p.intake = { vax: "Up to date", complaint: p.caseDef.complaint, triage: "Routine" }; p.record.push(`${clockStr()} — Registered by ${rc.name} (receptionist).`); addXP(5); const idx = G.patients.filter(x => x.status === "waiting").length; walkNPC(p, PATH.deskToWait(idx), "waiting"); reflowQueue(); toast(`${rc.name} registered ${p.name}.`, "info", 2000); } } }
  // nurse handles routine checkups from the waiting room
  const nu = st("nurse"); if (nu) { G.nurseTimer -= dt; if (G.nurseTimer <= 0) { G.nurseTimer = 20; const p = G.patients.find(x => x.status === "waiting" && x.caseDef.outcome === "checkup" && !x.emergency && !x.mystery && !x.caseDef.needs && !["rabbit", "tortoise"].includes(x.species)); if (p && !patientAt("nurse")) { p.status = "nurse"; p.npc.path = PATH.waitToExam.slice(); p.npc.onArrive = () => { World.placePet(p.npc, 6.5, 1.0, -7, Math.PI / 2); p.npc.rig.group.position.set(5.6, 0, -6.1); setTimeout(() => { if (p.status !== "nurse") return; let note = `${clockStr()} — Routine checkup by ${nu.name} (nurse): ${p.caseDef.options[p.caseDef.correct]}.`; if (nu.level === "junior" && Math.random() < 0.12) { note += " Weight mis-recorded by the junior nurse — corrected on review."; rep(-0.05, "nurse recording error"); } p.record.push(note); p.fee = Math.round(p.caseDef.fee * 0.8); addXP(10, `${nu.name} finished a checkup`); if (p.rx && nu.level === "senior") { p.rxDone = true; p.record.push(`${clockStr()} — ${DRUGS.find(d => d.id === p.rx).name} dispensed by senior nurse.`); } sendToDesk(p, PATH.examToDesk); }, 25000); }; updateHUD(); } } }
  // shopkeeper
  const sk = st("shopkeeper"); if (sk && G.shopCustomer) { G.shopCustomer.t += dt * 2; if (G.shopCustomer.t > 30) { const it = SHOP_ITEMS.find(i => i.id === G.shopCustomer.wants); if (G.s.stock[it.id] > 0) { G.s.stock[it.id]--; G.s.itemsSold++; stat("sales"); earn(it.price); toast(`${sk.name} sold ${it.name}.`, "good", 2000); } G.shopCustomer = null; } }
  // cleaner raises hygiene slowly
  const cl = st("cleaner"); if (cl) s.hygiene = Math.min(100, s.hygiene + dt * (cl.level === "senior" ? 0.05 : 0.03));
}

/* ---------------- goals ---------------- */
function checkGoals() { const d = G.s.dayStats; (G.s.goals.list || []).forEach(g => { g.progress = d[g.key] || 0; if (!g.done && g.progress >= g.target) { g.done = true; Sound.success(); toast(`${icon("check", 16)} Goal: ${g.text} (+${g.reward} JD at close)`, "good", 3500); addXP(15); } }); }

/* ---------------- events, weather, story ---------------- */
function applyWeather() { const ev = G.s.event ? EVENTS.find(e => e.id === G.s.event.id) : null; const w = G.s.settings.weather === "auto" ? (ev ? ev.weather : "clear") : G.s.settings.weather; World.setWeather(w); }
function storyEffect(st) {
  const s = G.s; if (st.effect === "rival") s.story.rival = true; if (st.effect === "charity") s.story.charity = true; if (st.effect === "referral") s.story.referral = true;
  openPanel(`${icon("tag", 20)} ${st.title}`, `<p class="big">${st.text}</p>${st.effect === "inspector" ? `<div class="btnrow"><button class="btn primary" onclick="inspectorQuiz()">Begin the audit</button></div>` : st.effect === "board" ? `<p>Sit the exam from the office desk whenever you're ready.</p><div class="btnrow"><button class="btn primary" onclick="closePanel()">Understood</button></div>` : `<div class="btnrow"><button class="btn primary" onclick="closePanel()">Understood</button></div>`}`, { noClose: true });
  if (st.effect === "board") s.story.boardReady = true;
}
function runQuiz(title, questions, onDone) {
  let i = 0, score = 0; const ask = () => { const q = questions[i]; if (!q) return onDone(score, questions.length); const order = q.a.map((a, k) => k).sort(() => Math.random() - 0.5); openPanel(`${icon("book", 20)} ${title} — ${i + 1}/${questions.length}`, `<p class="big">${q.q}</p>${order.map(k => `<button class="btn opt" data-k="${k}">${q.a[k]}</button>`).join("")}`, { noClose: true }); document.querySelectorAll("#panelBody .opt").forEach(b => b.onclick = () => { const ok = +b.dataset.k === q.c; if (ok) { score++; Sound.success(); } else Sound.error(); quizRecord(q, ok); setBody(`<div class="${ok ? "goodbox" : "badbox"}"><b>${ok ? "Correct." : "Incorrect."}</b> ${q.q} → <b>${q.a[q.c]}</b></div><div class="btnrow"><button class="btn primary" id="qn">Next</button></div>`); $("#qn").onclick = () => { i++; ask(); }; }); }; ask();
}
function inspectorQuiz() { const qs = QUIZ_BANK.filter(q => q.topic === "asepsis").sort(() => Math.random() - 0.5).slice(0, 5); runQuiz("Board inspection", qs, (score, n) => { const pass = score >= 4 && G.s.hygiene >= 60; if (pass) { G.s.story.accredited = true; rep(0.5, "clinic accredited"); award("accredited"); confetti(); } else rep(-0.4, "failed inspection"); openPanel(`${icon(pass ? "check" : "warn", 20)} Inspection result`, `<div class="${pass ? "goodbox" : "badbox"}"><b>${score}/${n} correct · hygiene ${G.s.hygiene}%.</b> ${pass ? "The inspector signs your accreditation certificate — hang it in the office." : "The inspector issues a warning. Review the asepsis reference and keep the clinic clean; the audit repeats next week."}</div><div class="btnrow"><button class="btn primary" onclick="closePanel()">Close</button></div>`); if (!pass) G.s.story.seen = G.s.story.seen.filter(x => x !== "inspector"); save(); }); }
function boardExam() { const qs = QUIZ_BANK.slice().sort(() => Math.random() - 0.5).slice(0, 20); runQuiz("Board certification exam", qs, (score, n) => { const pass = score >= 16; if (pass) { G.s.story.certified = true; award("certified"); confetti(); rep(0.5, "board certified"); } openPanel(`${icon(pass ? "trophy" : "warn", 20)} Exam result`, `<div class="${pass ? "goodbox" : "badbox"}"><b>${score}/${n}.</b> ${pass ? "Congratulations, Dr. Ahmad — Diplomate. Prestige mode is now available from the office desk." : "Not this time (16/20 needed). Study the library and try again tomorrow."}</div><div class="btnrow"><button class="btn primary" onclick="closePanel()">Close</button></div>`); save(); }); }
function prestige() { const s = G.s; if (!s.story.certified) return; const keep = { achievements: s.achievements, collections: s.collections, clients: [], textbook: s.textbook, settings: s.settings, avatar: s.avatar, theme: s.theme, clinicName: s.clinicName, leaderboard: s.leaderboard, weekly: s.weekly, customNames: s.customNames, quiz: s.quiz, seenTutorial: true }; const n = defaultState(); Object.assign(n, keep); n.story.prestige = (s.story.prestige || 0) + 1; n.rep = 3.5; n.money = 600; n.staff = [{ role: "nurse", level: "senior", wage: STAFF_ROLES.nurse.wage.senior, name: pick(STAFF_NAMES), days: 0 }]; G.s = n; save(); location.reload(); }

/* ---------------- pharmacy ---------------- */
function uiPharmacy() {
  const pending = G.patients.filter(p => p.rx && !p.rxDone && ["ready_discharge", "to_desk", "recovery", "ward_ready", "dental_ready"].includes(p.status));
  const list = pending.map(p => `<button class="btn opt" onclick="dispense(${p.id})">${SPECIES[p.species].emoji} <b>${p.name}</b> (${p.weight} kg) — ${DRUGS.find(d => d.id === p.rx).name}</button>`).join("");
  const formulary = DRUGS.map(d => `<tr><td><b>${d.name}</b><br><span class="muted">${d.cls}</span></td><td>${Object.entries(d.dose).map(([k, v]) => `${SPECIES[k] ? SPECIES[k].label : k}: ${v} mg/kg`).join("<br>")}</td><td>${d.form}<br>${d.route}</td><td class="muted small">${d.note}</td></tr>`).join("");
  openPanel(`${icon("drug", 20)} Pharmacy`, `${pending.length ? `<h4>Prescriptions to dispense</h4>${list}` : "<p class='muted'>No prescriptions waiting.</p>"}<h4>Practice a dose</h4><div class="btnrow"><button class="btn" onclick="dosePractice()">Random dose calculation</button></div><h4>Formulary</h4><div class="scrollx"><table class="ref small">${formulary}</table></div>`, { wide: true });
}
function dispense(id) { const p = G.patients.find(x => x.id === id); const drug = DRUGS.find(d => d.id === p.rx); uiDoseTask(p, drug.id, () => { p.rxDone = true; p.record.push(`${clockStr()} — ${drug.name} dispensed with written instructions.`); closePanel(); toast(`${drug.name} dispensed for ${p.name}.`, "good"); }); }
function dosePractice() { const sp = pick(["dog", "cat", "rabbit", "bird"]); const d = pick(DRUGS.filter(x => x.dose[sp] && x.conc)); const w = +(rnd(SPECIES[sp].weight[0], SPECIES[sp].weight[1]).toFixed(sp === "bird" ? 3 : 1)); MGpanel(`Practice — ${d.name}`, (el) => MG.dose(el, d, sp, w), { icon: "drug" }).then(r => { if (r.ok) { G.s.dosesDone++; stat("doses"); addXP(10, "dose practice"); } uiPharmacy(); }); }

/* ---------------- lab ---------------- */
function labPanelHTML(species, scenarioKey) { const ref = LAB[species] || LAB.dog; const sc = LAB_SCENARIOS[scenarioKey]; return `<table class="ref small"><tr><th>Analyte</th><th>Result</th><th>Reference</th></tr>${Object.keys(ref).map(k => { const r = ref[k]; const mid = (r[0] + r[1]) / 2; const f = sc.changes[k] || 1; const val = +(mid * f * rnd(0.97, 1.03)).toFixed(k === "Creatinine" || k === "TP" ? 1 : 0); const cls = val < r[0] ? "low" : val > r[1] ? "high" : ""; return `<tr class="${cls}"><td>${k}</td><td><b>${val}</b> ${r[2]} ${cls ? (cls === "high" ? "▲" : "▼") : ""}</td><td class="muted">${r[0]}–${r[1]}</td></tr>`; }).join("")}</table>`; }
function uiLabPanel(p, next) {
  const key = p.caseDef.lab || (Math.random() < 0.25 ? pick(["dehydrated", "anaemia", "hepatic"]) : "normal"); const sc = LAB_SCENARIOS[key]; const order = [0, 1, 2].sort(() => Math.random() - 0.5);
  setBody(`<h4>Pre-anaesthetic bloods — ${p.name}</h4>${has("analyser") ? "<p class='muted'>In-house analyser: results in 8 minutes.</p>" : "<p class='muted'>Sent to the external lab (slower). Buy an in-house analyser in the office for instant results.</p>"}${labPanelHTML(p.species, key)}<p class="big">Interpretation?</p>${order.map(k => `<button class="btn opt" data-k="${k}">${sc.options[k]}</button>`).join("")}`);
  document.querySelectorAll("#panelBody .opt").forEach(b => b.onclick = () => { const ok = +b.dataset.k === sc.correct; if (ok) { Sound.success(); addXP(20, "lab panel interpreted"); G.s.labsDone++; stat("labs"); } else { Sound.error(); p.mistakes++; } p.record.push(`${clockStr()} — Bloods: ${sc.meaning.split(".")[0]} (${ok ? "interpreted correctly" : "misread, corrected"}).`); if (key !== "normal") p.asa = 3; setBody(`<div class="${ok ? "goodbox" : "badbox"}"><b>${ok ? "Correct." : "Not quite."}</b> ${sc.meaning}</div><div class="btnrow"><button class="btn primary" id="lb">Continue</button></div>`); $("#lb").onclick = next; });
}
function uiLab() { openPanel(`${icon("flask", 20)} Blood analyser`, `<p class="muted">${has("analyser") ? "In-house analyser online." : "Not purchased — samples go to an external lab (results still shown here for practice)."}</p><div class="btnrow"><button class="btn primary" onclick="labPractice()">Practice reading a panel</button></div><h4>Reference ranges</h4>${Object.keys(LAB).map(sp => `<details><summary>${SPECIES[sp].label}</summary>${labPanelHTML(sp, "normal")}</details>`).join("")}`, { wide: true }); }
function labPractice() { const sp = pick(["dog", "cat"]); const key = pick(Object.keys(LAB_SCENARIOS)); const sc = LAB_SCENARIOS[key]; const order = [0, 1, 2].sort(() => Math.random() - 0.5); openPanel(`${icon("flask", 20)} Lab practice — ${SPECIES[sp].label}`, `${labPanelHTML(sp, key)}<p class="big">Interpretation?</p>${order.map(k => `<button class="btn opt" data-k="${k}">${sc.options[k]}</button>`).join("")}`, { wide: true }); document.querySelectorAll("#panelBody .opt").forEach(b => b.onclick = () => { const ok = +b.dataset.k === sc.correct; if (ok) { Sound.success(); addXP(10, "lab practice"); G.s.labsDone++; stat("labs"); } else Sound.error(); setBody(`<div class="${ok ? "goodbox" : "badbox"}">${sc.meaning}</div><div class="btnrow"><button class="btn primary" onclick="labPractice()">Another</button><button class="btn" onclick="uiLab()">Back</button></div>`); }); }

/* ---------------- microscope, ultrasound, ECG, DDX practice ---------------- */
function uiMicroscope(p, next) {
  const key = pick(Object.keys(CYTOLOGY)); const opts = Object.keys(CYTOLOGY).sort(() => Math.random() - 0.5).slice(0, 4); if (!opts.includes(key)) opts[0] = key;
  openPanel(`${icon("flask", 20)} Microscope — 40× field`, `${MG.microscopeField(key)}<p class="big">What do you see?</p>${opts.map(k => `<button class="btn opt" data-k="${k}">${CYTOLOGY[k].label}</button>`).join("")}`, { wide: true });
  document.querySelectorAll("#panelBody .opt").forEach(b => b.onclick = () => { const ok = b.dataset.k === key; if (ok) { Sound.success(); addXP(15, "cytology identified"); } else Sound.error(); setBody(`${MG.microscopeField(key)}<div class="${ok ? "goodbox" : "badbox"}"><b>${CYTOLOGY[key].label}.</b> ${CYTOLOGY[key].dx}</div><div class="btnrow"><button class="btn primary" onclick="${next ? "closePanel()" : "uiMicroscope()"}">${next ? "Continue" : "Another slide"}</button></div>`); if (next) G.onPanelClose = next; });
}
function uiUltrasound() { if (!has("ultrasound")) return openPanel(`${icon("monitor", 20)} Ultrasound`, `<p>Not purchased. Buy it from the office desk (900 JD) to unlock scanning and abdominal cases.</p>`); MGpanel("Ultrasound practice", (el) => MG.ultrasound(el, pick(["fluid-filled uterus", "splenic mass with free fluid", "gastric foreign body", "distended bladder with calculi"])), { icon: "monitor" }).then(r => { if (r.ok) addXP(15, "scan captured"); closePanel(); }); }
function uiECGPractice() { const keys = Object.keys(ECG); const k = pick(keys); const opts = keys.slice().sort(() => Math.random() - 0.5).slice(0, 4); if (!opts.includes(k)) opts[0] = k; openPanel(`${icon("monitor", 20)} ECG rhythm practice`, `${MG.ecgStrip(k)}<p class="big">Identify the rhythm:</p>${opts.map(o => `<button class="btn opt" data-k="${o}">${ECG[o].label}</button>`).join("")}<h4>Monitoring targets</h4><ul><li>SpO₂ ≥ 95 % · ETCO₂ 35–45 mmHg · MAP ≥ 60 mmHg · Temp 37–39 °C</li></ul>`, { wide: true }); document.querySelectorAll("#panelBody .opt").forEach(b => b.onclick = () => { const ok = b.dataset.k === k; if (ok) { Sound.success(); addXP(10, "rhythm practice"); } else Sound.error(); setBody(`${MG.ecgStrip(k)}<div class="${ok ? "goodbox" : "badbox"}"><b>${ECG[k].label}.</b> ${ECG[k].action}</div><div class="btnrow"><button class="btn primary" onclick="uiECGPractice()">Another strip</button></div>`); }); }
function uiDDX(id) {
  const p = G.patients.find(x => x.id === id); const D = p.caseDef.ddx; if (!p.ddx) p.ddx = { tests: [] };
  const tests = { cbc: ["CBC", 25], chem: ["Biochemistry", 40], xray: ["Radiographs", 60], ultrasound: ["Ultrasound", 70], cytology: ["Cytology", 20], urinalysis: ["Urinalysis", 15] };
  openPanel(`${icon("flask", 20)} Differential board — ${p.name}`, `<div class="cols"><div><h4>Pinned symptoms</h4><div class="pins">${D.symptoms.map(s => `<span class="pin">${s}</span>`).join("")}</div><h4>Order tests (each costs the client)</h4>${Object.keys(tests).map(t => `<button class="btn small ${p.ddx.tests.includes(t) ? "done" : ""}" onclick="ddxTest(${id},'${t}')" ${p.ddx.tests.includes(t) ? "disabled" : ""}>${tests[t][0]} — ${tests[t][1]} JD</button>`).join(" ")}<h4>Results</h4><ul class="plain">${p.ddx.tests.map(t => `<li><b>${tests[t][0]}:</b> ${D.tests[t]}</li>`).join("") || "<li class='muted'>None yet.</li>"}</ul></div><div><h4>Differentials</h4>${D.dx.map((d, i) => `<button class="btn opt" onclick="ddxPick(${id},${i})">${d}</button>`).join("")}${hint("Good clinicians reach the diagnosis with the fewest tests that discriminate between differentials — a detective, not a shotgun.")}</div></div>`, { wide: true });
}
function ddxTest(id, t) { const p = G.patients.find(x => x.id === id); p.ddx.tests.push(t); Sound.beep(); uiDDX(id); }
function ddxPick(id, i) { const p = G.patients.find(x => x.id === id); const D = p.caseDef.ddx; const ok = i === D.correct; const needed = D.needed.every(t => p.ddx.tests.includes(t)); const extra = p.ddx.tests.length - D.needed.length; const score = (ok ? 60 : 0) + (needed ? 20 : 0) + Math.max(0, 20 - extra * 7); if (ok) { addXP(60 + Math.max(0, 20 - extra * 7), "mystery solved"); Sound.success(); award("detective"); G.s.correctDx++; } else { Sound.error(); p.mistakes++; rep(-0.2, "misdiagnosis"); } p.record.push(`${clockStr()} — Differential work-up: tests ${p.ddx.tests.join(", ") || "none"}; diagnosis "${D.dx[i]}" (${ok ? "correct" : "incorrect"}).`); setBody(`<div class="${ok ? "goodbox" : "badbox"}"><b>${ok ? "Correct" : "Incorrect"} — ${D.dx[D.correct]}.</b> ${p.caseDef.why} Score ${score}/100 (${extra > 0 ? extra + " unnecessary test(s)" : "efficient work-up"}).</div><div class="btnrow"><button class="btn primary" onclick="diagnose(${id},${p.caseDef.correct})">Plan</button></div>`); }
function uiDDXPractice() { const m = pick(CASES.filter(c => c.ddx)); const fake = { id: -1, name: "Practice case", caseDef: m, species: m.species, record: [], mistakes: 0 }; G.patients.push(fake); uiDDX(-1); G.onPanelClose = () => { G.patients = G.patients.filter(x => x.id !== -1); }; }

/* ---------------- dental & ward ---------------- */
function uiDental() { const p = patientAt("dental_ready"); if (!p) return openPanel(`${icon("tooth", 20)} Dental suite`, `<p>${has("dentalmachine") ? "No dental patient. Dental cases arrive from the exam room." : "You own the room but not the dental unit — buy it from the office."}</p><p class="muted">Modified Triadan: 100s upper right, 200s upper left, 300s lower left, 400s lower right. Canine = 04, carnassials = 108/208 and 309/409.</p>`); const lesions = p.species === "cat" ? { forl: 1, forl2: 1, calculus: 1 } : { calculus: 1, fracture: 1, mobile: 1 }; const les = {}; Object.keys(lesions).forEach(k => les[k.replace(/\d/, "")] = 1); MGpanel(`Dental — ${p.name}`, (el) => MG.dental(el, p.species, les), { icon: "tooth" }).then(r => { p.record.push(`${clockStr()} — Dental: scale & polish, extractions as charted (${r.ok ? "no errors" : "errors corrected"}).`); if (r.ok) { addXP(60, "dental complete"); award("dentist"); } else p.mistakes++; p.fee = p.caseDef.fee; closePanel(); sendToDesk(p, PATH.dentalToDesk); }); }
function uiWard() { const p = patientAt("ward_ready"); if (!p) return openPanel(`${icon("bed", 20)} Exotics & isolation ward`, "<p>Heated kennels for rabbits, tortoises and birds; the isolation bay has its own PPE station, dedicated instruments and a footbath.</p>"); const iso = p.caseDef.isolation; const steps = iso ? ["Gown, gloves, shoe covers at the isolation door", "Dedicated thermometer & stethoscope stay in the bay", "IV fluids, anti-emetic, antibiotics for sepsis risk", "Bleach 1:30 for all surfaces; footbath on exit"] : p.species === "rabbit" ? ["Warm to 38.5 °C, quiet dark kennel", "Analgesia + SC fluids 100 mL/kg/day", "Syringe-feed critical-care formula, prokinetic", "Check molars with an otoscope for spurs"] : ["Warm to POTZ 26–32 °C with UVB", "Warm-water soak 20 min for hydration", "Nasal flush & cytology; vitamin A assessment", "Husbandry sheet for the owner"]; let i = 0; const show = () => { if (i >= steps.length) { p.record.push(`${clockStr()} — Ward care: ${steps.join("; ")}.`); addXP(40, "ward care complete"); if (iso) award("isolation"); p.fee = p.caseDef.fee; closePanel(); sendToDesk(p, PATH.wardToDesk); return; } openPanel(`${icon("bed", 20)} Ward — ${p.name}`, `${iso ? `<div class="alarmbox"><b>ISOLATION.</b> Everything that enters stays or is disinfected.</div>` : ""}<div class="step cur"><span class="chk">${i + 1}</span><div><b>${steps[i]}</b></div></div><div class="btnrow"><button class="btn primary" id="wn">Done</button></div>`, { noClose: true }); $("#wn").onclick = () => { i++; Sound.click(); show(); }; }; show(); }

/* ---------------- van / farm calls ---------------- */
function uiVan() { if (!has("van")) return openPanel(`${icon("van", 20)} Mobile vet van`, "<p>Buy the van in the office (1500 JD) to answer farm calls and run vaccination camps.</p>"); if (!G.s.shiftActive) return openPanel(`${icon("van", 20)} Mobile vet van`, "<p>Farm calls come in during a shift.</p>"); const calls = CASES.filter(c => c.farm && c.level <= G.s.level); const c = pick(calls); openPanel(`${icon("van", 20)} Farm call`, `<p class="big">${c.complaint}</p><p class="muted">Driving out takes 45 clinic-minutes; the clinic keeps running (staff cover what they can).</p><div class="btnrow"><button class="btn primary" onclick="farmCall('${c.id}')">Drive out</button><button class="btn" onclick="vaccCamp()">Run a vaccination camp instead</button></div>`); }
function farmCall(cid) { const c = CASES.find(x => x.id === cid); G.s.clockMin += 45; const fake = { id: -2, name: c.id === "farm_goat" ? "the goat" : "the horse", caseDef: c, species: "dog", record: [], mistakes: 0, weight: c.id === "farm_goat" ? 45 : 480 }; const order = [0, 1, 2].sort(() => Math.random() - 0.5); openPanel(`${icon("van", 20)} On the farm`, `<p>${c.findings}</p><p class="big">Plan?</p>${order.map(k => `<button class="btn opt" data-k="${k}">${c.options[k]}</button>`).join("")}`, { noClose: true }); document.querySelectorAll("#panelBody .opt").forEach(b => b.onclick = () => { const ok = +b.dataset.k === c.correct; if (ok) { Sound.success(); addXP(40, "farm call"); } else { Sound.error(); rep(-0.1, "farm call error"); } const after = () => { earn(c.fee); award("farmvet"); closePanel(); toast(`Farm call done — ${c.fee} JD.`, "good"); }; setBody(`<div class="${ok ? "goodbox" : "badbox"}">${c.why}</div><div class="btnrow"><button class="btn primary" id="fc">${c.id === "farm_goat" ? "Drain the abscess" : "Finish & drive back"}</button></div>`); $("#fc").onclick = () => { if (c.id === "farm_goat") runProcedureSteps(fake, "hoof").then(after); else after(); }; }); }
function vaccCamp() { let n = 0, errs = 0; const qs = [["Puppy, 8 weeks, first visit", "DHPP (core); rabies from 12 weeks", ["DHPP core vaccine", "Rabies only", "No vaccine — too young"]], ["Adult cat, indoor, overdue 2 years", "FVRCP booster; rabies per law", ["FVRCP booster + rabies", "Kitten series from scratch ×3", "Feline leukaemia only"]], ["Dog, vaccinated last month, fever today", "Do not vaccinate a sick animal — examine and treat first", ["Postpone, examine the fever", "Vaccinate anyway", "Double dose to catch up"]], ["Kitten, 14 weeks, had one FVRCP at 8 weeks", "Needs boosters at 12 and 16 weeks — give one now and book the last", ["FVRCP booster now, final at 16 weeks", "Fully vaccinated already", "Rabies only"]], ["Adult dog, lives rurally with livestock", "Core + leptospirosis (non-core but risk-based)", ["DHPP + leptospirosis", "Core only, no discussion", "Kennel cough only"]]]; const ask = () => { if (n >= qs.length) { const fee = 25 * qs.length; earn(fee); addXP(50 - errs * 8, "vaccination camp"); award("camp"); G.s.clockMin += 60; return openPanel(`${icon("van", 20)} Camp finished`, `<div class="goodbox">${qs.length} animals vaccinated, ${errs} error(s). +${fee} JD. Certificates issued.</div><div class="btnrow"><button class="btn primary" onclick="closePanel()">Drive back</button></div>`); } const q = qs[n]; const order = [0, 1, 2].sort(() => Math.random() - 0.5); openPanel(`${icon("van", 20)} Vaccination camp — ${n + 1}/${qs.length}`, `<p class="big">${q[0]}</p>${order.map(k => `<button class="btn opt" data-k="${k}">${q[2][k]}</button>`).join("")}`, { noClose: true }); document.querySelectorAll("#panelBody .opt").forEach(b => b.onclick = () => { const ok = +b.dataset.k === 0; if (!ok) errs++; Sound[ok ? "success" : "error"](); setBody(`<div class="${ok ? "goodbox" : "badbox"}">${q[1]}</div><div class="btnrow"><button class="btn primary" id="vn">Next</button></div>`); $("#vn").onclick = () => { n++; ask(); }; }); }; ask(); }

/* ---------------- office: customise, equipment, expansions, settings, backup ---------------- */
function uiOffice() {
  const s = G.s; const t = s.theme; const sw = (key, cols) => cols.map(c => `<span class="swatch ${t[key] === c ? "sel" : ""}" style="background:${c}" onclick="setTheme('${key}','${c}')"></span>`).join("");
  const asw = (key, cols) => cols.map(c => `<span class="swatch ${s.avatar[key] === c ? "sel" : ""}" style="background:${c}" onclick="setAvatar('${key}','${c}')"></span>`).join("");
  const eq = EQUIPMENT.map(e => `<div class="shopitem"><span class="icw">${icon(e.icon, 24)}</span><div><b>${e.name}</b> — ${e.price} JD<br><span class="muted">${e.desc}</span><div class="btnrow tight">${has(e.id) ? `<span class="muted">${T("Owned")}</span>` : e.needs && !owns(e.needs) ? `<span class="muted">Needs the ${EXPANSIONS.find(x => x.id === e.needs).name}</span>` : `<button class="btn small primary" onclick="buyEquipment('${e.id}')">${T("Buy")}</button>`}</div></div></div>`).join("");
  const ex = EXPANSIONS.map(e => `<div class="shopitem"><span class="icw">${icon(e.icon, 24)}</span><div><b>${e.name}</b> — ${e.price} JD<br><span class="muted">${e.desc}</span><div class="btnrow tight">${owns(e.id) ? `<span class="muted">${T("Owned")}</span>` : `<button class="btn small primary" onclick="buyExpansion('${e.id}')">${T("Buy")}</button>`}</div></div></div>`).join("");
  openPanel(`${icon("office", 20)} ${T("Office")}`, `
    <div class="tabs"><button class="tab on" data-tab="manage">Manage</button><button class="tab" data-tab="style">Customise</button><button class="tab" data-tab="backup">Backup & settings</button></div>
    <div class="tabpane" id="tab-manage"><h4>Clinic statistics</h4><ul class="plain cols3"><li>Day ${s.day} · Lv ${s.level} · ${s.xp} XP</li><li>Balance ${fmtMoney(s.money)}</li><li>Reputation ${s.rep.toFixed(1)} ★</li><li>Patients ${s.patientsSeen}</li><li>Surgeries ${s.surgeries}</li><li>Clients on file ${s.clients.length}</li><li>Hygiene ${s.hygiene}%</li><li>Staff ${s.staff.length}</li><li>Cases ${s.cases.length}</li></ul>
      <h4>Equipment</h4><div class="shopgrid">${eq}</div><h4>Expansions</h4><div class="shopgrid">${ex}</div>
      ${s.story.boardReady && !s.story.certified ? `<div class="alarmbox"><b>Board exam available.</b> 20 questions, 16 to pass. <button class="btn primary small" onclick="boardExam()">Sit the exam</button></div>` : ""}
      ${s.story.certified ? `<div class="goodbox"><b>Diplomate.</b> Prestige ${s.story.prestige || 0}. Start a new clinic with permanent perks (a senior nurse, +0.5 ★, achievements & collections kept). <button class="btn small warn" onclick="if(G.confirmPrestige){prestige()}else{G.confirmPrestige=true;toast('Click again to confirm Prestige — current day/money/staff reset.','warn')}">Prestige</button></div>` : ""}
      ${s.story.accredited ? `<p>${icon("check", 14)} Accredited by the veterinary board.</p>` : ""}</div>
    <div class="tabpane hidden" id="tab-style"><label>Clinic name <input id="cName" value="${s.clinicName}" maxlength="28"></label><button class="btn primary" onclick="renameClinic()">Rename (updates the sign)</button>
      <h4>Walls</h4><div class="swatches">${sw("wall", ["#2a2f4a", "#1f2235", "#2b2b3f", "#33264a", "#1e2a3a", "#3a3f55"])}</div>
      <h4>Accent</h4><div class="swatches">${sw("accent", ["#f2c14e", "#7c6fcf", "#5f8fd6", "#e07a5f", "#4fb3a9", "#b4557a"])}</div>
      <h4>Trim</h4><div class="swatches">${sw("trim", ["#4b4f7a", "#5a3e8f", "#3f6f6a", "#6e4b36", "#444a66", "#2f4f8f"])}</div>
      <h4>Floors</h4><div class="swatches">${sw("floor", ["#3b3f5c", "#2f3550", "#2e4a44", "#4a3d33", "#332f4e", "#2b2b3f"])}</div>
      <h4>Dr. Ahmad — coat</h4><div class="swatches">${sw("coat", ["#e9e9f2", "#cfd8ff", "#f2c14e", "#9ea4c4", "#4fb3a9", "#2a2f4a"])}</div>
      <h4>Scrubs</h4><div class="swatches">${asw("scrub", ["#2f4f8f", "#3f6f6a", "#5a3e8f", "#b4557a", "#4fb3a9", "#23222e"])}</div>
      <h4>Cap</h4><div class="swatches">${asw("cap", ["#2f4f8f", "#f2c14e", "#7c6fcf", "#e07a5f", "#4fb3a9", "#dfe3ee"])}</div>
      <h4>Glasses frames</h4><div class="swatches">${asw("frames", ["#2d2438", "#f2c14e", "#8a3350", "#5f8fd6", "#dfe3ee"])}</div>
      <label class="row"><input type="checkbox" id="cDecor" ${t.decor !== false ? "checked" : ""} onchange="setTheme('decor',this.checked)"> Plants & posters</label></div>
    <div class="tabpane hidden" id="tab-backup">${backupHTML()}<div class="btnrow"><button class="btn" onclick="uiSettings()">${icon("settings", 16)} ${T("Settings")}</button><button class="btn warn small" onclick="resetGame()">${T("Reset all progress")}</button></div></div>`, { wide: true });
  wireTabs();
}
function wireTabs() { document.querySelectorAll("#panelBody .tab").forEach(b => b.onclick = () => { document.querySelectorAll("#panelBody .tab").forEach(x => x.classList.toggle("on", x === b)); document.querySelectorAll("#panelBody .tabpane").forEach(p => p.classList.toggle("hidden", p.id !== "tab-" + b.dataset.tab)); }); }
function buyEquipment(id) { const e = EQUIPMENT.find(x => x.id === id); if (G.s.money < e.price) return toast("Not enough money.", "warn"); G.s.money -= e.price; G.s.equipment.push(id); Sound.cash(); toast(`${e.name} installed.`, "good"); award("investor"); uiOffice(); updateHUD(); save(); }
function buyExpansion(id) { const e = EXPANSIONS.find(x => x.id === id); if (G.s.money < e.price) return toast("Not enough money.", "warn"); G.s.money -= e.price; G.s.expansions.push(id); World.setLocked(id, false); Sound.unlock(); confetti(); toast(`${e.name} opened! New cases will start arriving.`, "good", 4000); award("expansion"); uiOffice(); updateHUD(); save(); }
function setTheme(k, v) { G.s.theme[k] = v; award("decorator"); applyTheme(); Sound.click(); uiOffice(); document.querySelector('[data-tab="style"]').click(); save(); }
function setAvatar(k, v) { G.s.avatar[k] = v; World.applyAvatar(G.s.avatar); Sound.click(); uiOffice(); document.querySelector('[data-tab="style"]').click(); save(); }
function applyTheme() { const t = G.s.theme; World.applyTheme({ wall: parseInt(t.wall.slice(1), 16), accent: parseInt(t.accent.slice(1), 16), trim: parseInt(t.trim.slice(1), 16), floor: t.floor ? parseInt(t.floor.slice(1), 16) : null, coat: parseInt(t.coat.slice(1), 16), decor: t.decor !== false }); document.documentElement.style.setProperty("--accent", t.accent); document.documentElement.style.setProperty("--trim", t.trim); document.documentElement.style.setProperty("--onaccent", luma(t.accent) > 0.5 ? "#1b1a12" : "#ffffff"); }
function luma(hex) { const n = parseInt(hex.slice(1), 16); return (0.299 * (n >> 16) + 0.587 * ((n >> 8) & 255) + 0.114 * (n & 255)) / 255; }
function renameClinic() { const n = $("#cName").value.trim(); if (!n) return; G.s.clinicName = n; World.setSign(n); award("decorator"); updateHUD(); toast(`Sign updated: ${n}`, "good"); save(); }
function resetGame() { if (!G.confirmReset) { G.confirmReset = true; return toast("Click again to confirm the full reset (export a backup first!).", "warn"); } try { localStorage.removeItem(SAVE_KEY); } catch (e) { } location.reload(); }

/* ---------- backup & restore ---------- */
function backupHTML() { return `<h4>${icon("folder", 16)} Backup & restore</h4><p class="muted">Your progress is saved automatically in this browser. To move it to another device or keep it safe across game updates, download a backup file (or copy the code). Restoring replaces the current save.</p><div class="btnrow"><button class="btn primary" onclick="downloadBackup()">${icon("arrow", 16)} Download backup file</button><button class="btn" onclick="copyBackup()">Copy backup code</button><label class="btn filebtn">Restore from file <input type="file" accept=".json,application/json,.txt" onchange="restoreFromFile(this)"></label></div><label>…or paste a backup code <textarea id="restoreCode" rows="2" placeholder="BCSAVE…"></textarea></label><button class="btn" onclick="restoreFromCode()">Restore from code</button><p class="muted small">Backup files from older versions are upgraded automatically when restored.</p>`; }
function backupString() { save(); return "BCSAVE1." + btoa(unescape(encodeURIComponent(JSON.stringify(G.s)))); }
function downloadBackup() { try { const blob = new Blob([JSON.stringify({ format: "batman-clinic-backup", version: 2, exported: new Date().toISOString(), state: G.s }, null, 0)], { type: "application/json" }); const a = document.createElement("a"); a.href = URL.createObjectURL(blob); a.download = `batman-clinic-backup-day${G.s.day}.json`; document.body.appendChild(a); a.click(); setTimeout(() => { URL.revokeObjectURL(a.href); a.remove(); }, 500); toast("Backup downloaded. Keep it somewhere safe (Files / iCloud / Drive).", "good", 4000); } catch (e) { toast("Download blocked here — use “Copy backup code” instead.", "warn", 4000); } }
function copyBackup() { const code = backupString(); try { navigator.clipboard.writeText(code).then(() => toast("Backup code copied — paste it into Notes or a message to yourself.", "good", 4000)).catch(() => showCode(code)); } catch (e) { showCode(code); } }
function showCode(code) { setBody(`<p>Select all and copy:</p><textarea rows="8" style="width:100%" readonly>${code}</textarea><div class="btnrow"><button class="btn" onclick="uiOffice()">Back</button></div>`); }
function applyRestoredState(obj) { try { const st = obj.state || obj; if (!st || typeof st !== "object" || !("money" in st) || !("day" in st)) throw new Error("not a save"); localStorage.setItem(SAVE_KEY, JSON.stringify(st)); toast("Backup restored — reloading…", "good", 2000); setTimeout(() => location.reload(), 900); } catch (e) { toast("That file/code is not a Batman Clinic backup.", "warn", 4000); } }
function restoreFromFile(input) { const f = input.files && input.files[0]; if (!f) return; const r = new FileReader(); r.onload = () => { try { applyRestoredState(JSON.parse(r.result)); } catch (e) { const t = String(r.result).trim(); if (t.startsWith("BCSAVE1.")) restoreCodeString(t); else toast("Could not read that backup file.", "warn"); } }; r.readAsText(f); }
function restoreFromCode() { restoreCodeString(($("#restoreCode").value || "").trim()); }
function restoreCodeString(code) { if (!code.startsWith("BCSAVE1.")) return toast("Codes start with BCSAVE1.", "warn"); try { applyRestoredState(JSON.parse(decodeURIComponent(escape(atob(code.slice(8)))))); } catch (e) { toast("That code is damaged or incomplete.", "warn"); } }

/* ---------------- settings ---------------- */
function uiSettings() {
  const st = G.s.settings; const opt = (name, val, label) => `<button class="btn small ${st[name] === val ? "primary" : ""}" onclick="setSetting('${name}',${typeof val === "string" ? `'${val}'` : val})">${label}</button>`;
  openPanel(`${icon("settings", 20)} ${T("Settings")}`, `
    <h4>${T("Camera")}</h4><div class="btnrow tight">${opt("camMode", "third", T("Third person"))}${opt("camMode", "first", T("First person"))}</div><p class="muted">First person: ${G.touch ? "drag the screen to look around" : "move the mouse to look (click the game to lock the cursor)"}, move with ${G.touch ? "the D-pad" : "WASD"} relative to your view. Shortcut: <kbd>V</kbd>.</p>
    <h4>Difficulty</h4><div class="btnrow tight">${opt("difficulty", "student", "Student — hints, more time, gentle penalties")}${opt("difficulty", "vet", "Vet — standard")}${opt("difficulty", "specialist", "Specialist — timed steps, double penalties, fewer XP")}</div>
    <h4>Mentor hints</h4><div class="btnrow tight">${opt("hints", true, "On")}${opt("hints", false, "Off")}</div>
    <h4>${T("Language")} / اللغة</h4><div class="btnrow tight">${opt("lang", "en", "English")}${opt("lang", "ar", "العربية (واجهة)")}</div><p class="muted">Arabic covers the interface; clinical content stays in English for accuracy.</p>
    <h4>Text size</h4><div class="btnrow tight">${opt("textSize", 0.9, "Small")}${opt("textSize", 1, "Normal")}${opt("textSize", 1.15, "Large")}${opt("textSize", 1.3, "Extra large")}</div>
    <h4>One-handed phone layout</h4><div class="btnrow tight">${opt("oneHand", "left", "D-pad left")}${opt("oneHand", "right", "D-pad right")}</div>
    <h4>Music</h4><div class="btnrow tight">${opt("music", true, "On")}${opt("music", false, "Off")}</div>
    <h4>Weather</h4><div class="btnrow tight">${opt("weather", "auto", "Follow events")}${opt("weather", "rain", "Always rain")}${opt("weather", "clear", "Always clear")}</div>
    <h4>Co-op on one screen</h4><div class="btnrow tight">${opt("coop", false, "Off")}${opt("coop", true, "On — player 2 (nurse) uses I J K L + U")}</div><p class="muted">Player 2 runs reception, the bell and the shop while player 1 operates.</p>
    <h4>Classroom mode</h4><label>Case code (everyone with the same code gets the same next patient) <input id="classCode" placeholder="e.g. VET101" maxlength="16"></label><button class="btn small" onclick="classroomSpawn()">Queue that case</button>
    <div class="btnrow"><button class="btn" onclick="uiOffice()">${T("Back")}</button></div>`, { wide: true });
}
function setSetting(name, val) { G.s.settings[name] = val; if (name === "camMode") World.setCamMode(val); if (name === "coop") World.enableCoop(val); if (name === "music") { if (val && G.s.shiftActive) Sound.music.start("lobby"); else Sound.music.stop(); } if (name === "weather") applyWeather(); applySettingsToWorld(); Sound.click(); uiSettings(); save(); updateHUD(); }
function classroomSpawn() { const code = ($("#classCode").value || "").trim(); if (!code) return; const cs = seededCases(code); G.weeklyQueue = cs.slice(0, 1); G.weeklyMode = true; toast(`Classroom case ${code} queued — it arrives next when the shift is open.`, "good", 4000); }

/* ---------------- cases, library, quiz, collections ---------------- */
function uiCases() { const cs = G.s.cases.slice().reverse(); openPanel(`${icon("folder", 20)} Case files`, `${cs.length ? `<p class="muted">Select a case to view, replay the procedure, print it as a PDF, or share a card.</p><div class="caselist">${cs.map(c => `<button class="btn case" onclick="viewCase(${c.id})">${SPECIES[c.species].emoji} <b>${c.name}</b> — ${c.procedure} · Day ${c.day}${c.mistakes ? ` · ${c.mistakes} correction(s)` : " · clean"}</button>`).join("")}</div>` : "<p>No closed cases yet.</p>"}`, { wide: true }); }
function caseHTML(c) { return `<div class="casefile"><div class="chead"><div><h2>${G.s.clinicName}</h2><p>Dr. Ahmad, DVM${G.s.story.certified ? ", Diplomate" : ""} · Clinical record</p></div><div class="right"><p>Case #${String(c.id).padStart(4, "0")}</p><p>Day ${c.day}</p></div></div><table class="ref"><tr><th>Patient</th><td>${c.name}</td><th>Species / breed</th><td>${SPECIES[c.species].label} — ${c.breed}</td></tr><tr><th>Owner</th><td>${c.ownerName}</td><th>Age / sex</th><td>${c.age} / ${c.sex}</td></tr><tr><th>Weight</th><td>${c.weight} kg</td><th>Procedure</th><td>${c.procedure}</td></tr></table><h3>Presenting complaint</h3><p>${c.complaint}</p><h3>Clinical notes${c.surg ? " & procedure replay" : ""}</h3><ol class="notes">${c.record.map(r => `<li class="${/incorrect|error|corrected|misread/i.test(r) ? "err" : ""}">${r}</li>`).join("")}</ol>${c.xray ? `<h3>Imaging</h3><p>${c.xray.label}</p>${skeletonSVG(c.xray.view, c.xray.finding, 420, 310)}` : ""}<p class="sig">Signed: Dr. Ahmad ____________________</p></div>`; }
function viewCase(id) { const c = G.s.cases.find(x => x.id === id); if (!c) return; openPanel(`${icon("folder", 20)} Case #${String(c.id).padStart(4, "0")} — ${c.name}`, `${caseHTML(c)}<div class="btnrow"><button class="btn primary" onclick="printCase(${id})">${icon("print", 16)} Print / Save as PDF</button><button class="btn" onclick="copyCase(${id})">Copy as text</button>${c.surg ? `<button class="btn" onclick="shareCard('case',${id})">${icon("share", 16)} Share card</button>` : ""}<button class="btn" onclick="uiCases()">Back</button></div>`, { wide: true }); }
function printCase(id) { const c = G.s.cases.find(x => x.id === id); $("#printArea").innerHTML = caseHTML(c); try { window.print(); } catch (e) { toast("Printing is blocked in this preview — open the game from its own link to print PDFs, or use “Copy as text”.", "warn", 6000); } }
function copyCase(id) { const c = G.s.cases.find(x => x.id === id); const txt = `${G.s.clinicName} — Case #${c.id}\nPatient: ${c.name} (${SPECIES[c.species].label}, ${c.breed}, ${c.age}, ${c.sex}, ${c.weight} kg)\nOwner: ${c.ownerName}\nProcedure: ${c.procedure}\nComplaint: ${c.complaint}\n\n${c.record.join("\n")}`; try { navigator.clipboard.writeText(txt).then(() => toast("Case copied.", "good")).catch(() => fallbackCopy(txt)); } catch (e) { fallbackCopy(txt); } }
function fallbackCopy(txt) { setBody(`<p>Select and copy:</p><textarea rows="16" style="width:100%">${txt}</textarea><div class="btnrow"><button class="btn" onclick="uiCases()">Back</button></div>`); }
function uiLibrary() { openPanel(`${icon("book", 20)} ${T("Library")}`, `<div class="tabs"><button class="tab on" data-tab="refs">References</button><button class="tab" data-tab="text">Textbook (${G.s.textbook.length})</button><button class="tab" data-tab="quiz">Quiz & flashcards</button></div>
  <div class="tabpane" id="tab-refs"><div class="books">${REFERENCES.map(r => `<button class="btn book ${G.s.refsRead.includes(r.id) ? "read" : ""}" onclick="uiReference('${r.id}')"><span class="icw">${icon(r.icon, 22)}</span>${r.title}</button>`).join("")}</div></div>
  <div class="tabpane hidden" id="tab-text">${G.s.textbook.length ? G.s.textbook.map(k => `<div class="step done"><span class="chk">${icon("check", 16)}</span><div><b>${CASES.find(c => c.id === k).complaint}</b><div class="tip">${TEXTBOOK[k]}</div></div></div>`).join("") : "<p class='muted'>Every new kind of case you treat adds a page here.</p>"}</div>
  <div class="tabpane hidden" id="tab-quiz">${quizHTML()}</div>`, { wide: true }); wireTabs(); }
function uiReference(id) { const r = REFERENCES.find(x => x.id === id); if (!r) return; if (!G.s.refsRead.includes(id)) { G.s.refsRead.push(id); addXP(10, "reference read"); stat("refs"); if (G.s.refsRead.length >= 5) award("bookworm"); save(); } openPanel(`${icon(r.icon, 20)} ${r.title}`, r.body() + `<div class="btnrow"><button class="btn" onclick="uiLibrary()">Back to shelf</button></div>`, { wide: true }); if (id === "anatomy") { wireXrayHover($("#panelBody"), $("#boneLabel")); hookBoneCollection($("#panelBody")); } }
/* spaced repetition: box 1 = review every day, box 2 = every 3 days, box 3 = weekly */
function quizDue() { const q = G.s.quiz; return allQuizCards().filter(c => { const box = q.boxes[c.id] || 1; const last = q.last[c.id] || -99; const gap = [1, 1, 3, 7][box]; return G.s.day - last >= gap; }); }
function allQuizCards() { const cards = QUIZ_BANK.map((q, i) => ({ id: "q" + i, q: q.q, a: q.a, c: q.c })); Object.keys(TOOLS).slice(0, 12).forEach((k, i) => { const others = Object.keys(TOOLS).filter(x => x !== k).sort(() => Math.random() - 0.5).slice(0, 3); const a = [TOOLS[k].name].concat(others.map(o => TOOLS[o].name)); cards.push({ id: "t" + k, q: `Which instrument is this?<br>${toolSVG(k, 160, 64)}`, a, c: 0 }); }); return cards; }
function quizRecord(q, ok) { const id = q.id || ("q" + QUIZ_BANK.indexOf(q)); const b = G.s.quiz.boxes[id] || 1; G.s.quiz.boxes[id] = ok ? Math.min(3, b + 1) : 1; G.s.quiz.last[id] = G.s.day; }
function quizHTML() { const due = quizDue().length; const boxes = [1, 2, 3].map(b => Object.values(G.s.quiz.boxes).filter(x => x === b).length); return `<p>Spaced repetition: cards you get right move to a slower box; wrong answers come back tomorrow.</p><p><b>${due}</b> card(s) due today · Box 1: ${boxes[0]} · Box 2: ${boxes[1]} · Box 3: ${boxes[2]}</p><div class="btnrow"><button class="btn primary" onclick="startQuiz()">Review due cards</button><button class="btn" onclick="startQuiz(true)">Flashcards (study mode)</button></div>`; }
function startQuiz(study) { const cards = (study ? allQuizCards() : quizDue()).sort(() => Math.random() - 0.5).slice(0, 10); if (!cards.length) return toast("Nothing due — come back tomorrow.", "info"); if (study) { let i = 0; const show = () => { const c = cards[i]; if (!c) return uiLibrary(); openPanel(`${icon("book", 20)} Flashcard ${i + 1}/${cards.length}`, `<div class="flash"><p class="big">${c.q}</p><details><summary>Show answer</summary><p><b>${c.a[c.c]}</b></p></details></div><div class="btnrow"><button class="btn primary" id="fn">Next</button></div>`); $("#fn").onclick = () => { i++; show(); }; }; return show(); } runQuiz("Review", cards, (score, n) => { addXP(score * 5, "quiz review"); openPanel(`${icon("book", 20)} Review done`, `<div class="goodbox">${score}/${n} correct. +${score * 5} XP.</div><div class="btnrow"><button class="btn primary" onclick="uiLibrary()">Back</button></div>`); save(); }); }
function uiCollections() { const c = G.s.collections; const allBones = 60; openPanel(`${icon("heart", 20)} Thank-you wall & collections`, `<div class="cols"><div><h4>Thank-you cards: ${G.s.thankCards}</h4><p class="muted">Clients leave a card after a visit with no mistakes. They hang on the office wall.</p><h4>Species treated (${c.species.length}/5)</h4><p>${c.species.map(s => `${SPECIES[s].emoji} ${SPECIES[s].label}`).join(" · ") || "—"}</p></div><div><h4>Anatomy atlas: ${c.bones.length} bones named</h4><p class="muted small">${c.bones.slice(-15).join(" · ")}</p><h4>Instrument museum: ${c.tools.length}/${Object.keys(TOOLS).length}</h4><div class="toolgrid">${c.tools.map(t => toolSVG(t, 90, 36)).join("")}</div></div></div><h4>Local leaderboard (weekly challenge)</h4><ol>${(G.s.leaderboard || []).slice(0, 10).map(l => `<li>${l.name} — ${l.score} XP (${l.week})</li>`).join("") || "<li class='muted'>No entries yet.</li>"}</ol>${G.s.weekly.best ? `<label>Your name <input id="lbName" maxlength="16" placeholder="Dr. …"></label><button class="btn small" onclick="addLeaderboard()">Add my best (${G.s.weekly.best} XP)</button>` : ""}`, { wide: true }); }
function addLeaderboard() { const n = ($("#lbName").value || "Dr. Ahmad").trim(); G.s.leaderboard = (G.s.leaderboard || []).filter(l => !(l.name === n && l.week === G.s.weekly.week)); G.s.leaderboard.push({ name: n, score: G.s.weekly.best, week: G.s.weekly.week }); G.s.leaderboard.sort((a, b) => b.score - a.score); save(); uiCollections(); }

/* ---------------- sharing, photo, radio, news, briefing, help ---------------- */
function shareCard(kind, id) {
  const c = document.createElement("canvas"); c.width = 900; c.height = 500; const ctx = c.getContext("2d");
  const g = ctx.createLinearGradient(0, 0, 900, 500); g.addColorStop(0, "#232a4d"); g.addColorStop(1, "#0d101f"); ctx.fillStyle = g; ctx.fillRect(0, 0, 900, 500);
  ctx.strokeStyle = "#f2c14e"; ctx.lineWidth = 6; ctx.strokeRect(20, 20, 860, 460); ctx.fillStyle = "#f2c14e"; ctx.font = "bold 44px Nunito, sans-serif"; ctx.fillText(G.s.clinicName, 50, 90); ctx.fillStyle = "#9ea4c4"; ctx.font = "22px Nunito, sans-serif"; ctx.fillText("Dr. Ahmad · Vet Simulator", 50, 125);
  let lines = []; if (kind === "surgery" || kind === "case") { const p = kind === "surgery" ? G.patients.find(x => x.id === id) : null; const r = p ? p.surgResult : (G.s.cases.find(x => x.id === id) || {}).surg; const name = p ? p.name : (G.s.cases.find(x => x.id === id) || {}).name; lines = [`${r.proc}`, `Patient: ${name}`, `${r.mistakes === 0 ? "FLAWLESS" : r.mistakes + " error(s)"} · ${r.mins} min`]; } else lines = [`Day ${G.s.day - 1} complete`, `${G.s.dayStats.patients || 0} patients · ${G.s.dayStats.surgeries || 0} surgeries`, `Reputation ${G.s.rep.toFixed(1)} ★ · Level ${G.s.level}`];
  ctx.fillStyle = "#fff"; ctx.font = "bold 40px Nunito, sans-serif"; lines.forEach((l, i) => ctx.fillText(l, 50, 220 + i * 62)); ctx.fillStyle = "#f2c14e"; ctx.font = "20px Nunito, sans-serif"; ctx.fillText("jenin-23.github.io/batman-clinic", 50, 450);
  const url = c.toDataURL("image/png");
  openPanel(`${icon("share", 20)} Share card`, `<img src="${url}" style="width:100%;border-radius:16px" alt="result card"><div class="btnrow"><a class="btn primary" href="${url}" download="batman-clinic-card.png">Download image</a><button class="btn" onclick="copyText('${lines.join(" · ").replace(/'/g, "")} — ${G.s.clinicName} (Batman Clinic vet simulator)')">Copy text</button><button class="btn" onclick="closePanel()">Close</button></div><p class="muted small">If the download does nothing here, long-press / right-click the image and save it.</p>`, { wide: true });
}
function copyText(t) { try { navigator.clipboard.writeText(t).then(() => toast("Copied.", "good")); } catch (e) { toast("Copy not available here.", "warn"); } }
function photoMode() { if (G.panelOpen) return; document.getElementById("hud").style.visibility = "hidden"; setTimeout(() => { const url = World.screenshot(); document.getElementById("hud").style.visibility = ""; if (!url) return toast("Screenshot not available on this device.", "warn"); openPanel(`${icon("camera", 20)} ${T("Photo mode")}`, `<img src="${url}" style="width:100%;border-radius:16px" alt="screenshot"><div class="btnrow"><a class="btn primary" href="${url}" download="batman-clinic-photo.png">Download</a><button class="btn" onclick="closePanel()">Close</button></div><p class="muted small">Tip: switch to first person (V) and frame Mishmish or a patient before pressing P.</p>`, { wide: true }); }, 50); }
function uiRadio() { openPanel(`${icon("sound", 20)} Staff room radio`, `<p>Take a breather. The radio plays a few quiet loops — pick a station.</p><div class="btnrow"><button class="btn" onclick="Sound.music.start('lobby');G.s.settings.music=true">Lobby lo-fi</button><button class="btn" onclick="Sound.music.start('night')">Night jazz</button><button class="btn" onclick="Sound.music.start('or')">Theatre focus</button><button class="btn warn" onclick="Sound.music.stop()">Off</button></div><p class="muted">Coffee: +1 morale (purely cosmetic, sadly).</p>`); }
const NEWS = ["v2 — Bigger clinic: Laboratory, Pharmacy, Staff Room, and two expansions (Dental Suite, Exotics & Isolation Ward).", "Hire staff with daily wages; reputation stars drive arrivals and fees; rent is due nightly.", "Emergencies with countdowns, rush hours, night shifts, weekly events and story arcs (rival clinic, charity, inspector, board exam, prestige).", "Hands-on surgery: clip & vacuum, scrub pattern, draping, ligature timing, suture trainer, bleeder clamp, swab count, pack assembly.", "Diagnostics: differential board, ultrasound, microscope cytology, lab panels, ECG rhythms, dental charts (Triadan), drug dose calculator.", "First-person camera (V), photo mode (P), co-op on one screen, Arabic interface, text size, difficulty levels, mentor hints.", "Backups: download a save file or copy a code from the office and restore it in any future version."];
function uiNews() { G.s.news = NEWS.length; openPanel(`${icon("tag", 20)} What's new`, `<ul>${NEWS.map(n => `<li>${n}</li>`).join("")}</ul><p class="muted">Source & updates: github.com/jenin-23/batman-clinic</p>`); }
function dailyBriefing() { const today = new Date().toISOString().slice(0, 10); if (G.s.lastBriefing === today) return; G.s.lastBriefing = today; const c = pick(CASES.filter(x => x.level <= G.s.level && !x.farm && !x.needs)); addXP(20, "daily briefing"); openPanel(`${icon("sun", 20)} Morning briefing`, `<p>Welcome back, Dr. Ahmad. Today's featured topic: <b>${c.complaint}</b></p><p class="muted">${c.why}</p><p>${quizDue().length} flashcards are due in the library. ${G.s.staff.length ? `Payroll today: ${staffWages()} JD.` : "Consider hiring a receptionist when the queue gets long."}</p><div class="btnrow"><button class="btn primary" onclick="closePanel()">Start the day</button></div>`); save(); }
function uiHelp() {
  openPanel(`${icon("paw", 20)} Welcome to ${G.s.clinicName}`, `<div class="cols"><div><h4>Controls</h4><ul class="plain"><li><kbd>W</kbd><kbd>A</kbd><kbd>S</kbd><kbd>D</kbd> / arrows — walk (<kbd>Shift</kbd> hurry)</li><li><kbd>E</kbd> / <kbd>Space</kbd> or tap the prompt — interact</li><li><kbd>V</kbd> first/third person · <kbd>P</kbd> photo · <kbd>O</kbd> settings · <kbd>H</kbd> help · <kbd>M</kbd> mute · <kbd>Esc</kbd> close</li><li>Phone/iPad: D-pad + Interact button; drag to look in first person</li></ul>
    <h4>You are Dr. Ahmad</h4><p>Run the clinic, treat dogs, cats, birds (and later rabbits and tortoises), learn real surgical technique, manage staff and reputation.</p>${hint("The clinic cat Mishmish wanders the building — pet her when you find her.")}</div>
    <div><h4>The patient pathway</h4><ol><li><b>Shift board</b> → start shift (goals + the week's event).</li><li><b>Reception</b> → talk to the owner, register.</li><li><b>Waiting room</b> → call the pet in.</li><li><b>Exam room</b> → read body language, full exam, assessment.</li><li><b>X-ray / Lab / Ultrasound</b> as needed.</li><li><b>Prep room</b> → checklist, bloods, doses, clip & scrub, pack at the autoclave.</li><li><b>Locker → Sink → Operating room</b> (the door checks your outfit).</li><li><b>Pharmacy</b> → dispense prescriptions. <b>Reception</b> → discharge.</li></ol><p>Also: shop, staff room (hire), office (equipment, expansions, customise, backups, settings), library (references, textbook, quiz).</p></div></div><div class="btnrow"><button class="btn primary" onclick="closePanel()">Start the day</button></div>`, { wide: true });
}
function registerSW() { try { if ("serviceWorker" in navigator && location.protocol === "https:" && !/claude\.ai|claudeusercontent/.test(location.hostname)) navigator.serviceWorker.register("sw.js").catch(() => { }); } catch (e) { } }
